@app.cell(hide_code=True)
def _(hurdle, money, social, tension_picker):
    tension_readings = [read_row for read_row in pack["tensions"]
                        if read_row["tension"] == tension_picker.value and read_row["parameter"]]
    legs = []
    for leg_row in tension_readings:
        run = (pack["runs"].get(f"tension:{leg_row['tension']}:{leg_row['value']}")
               or pack["runs"].get(f"sens:{leg_row['parameter']}={float(leg_row['value']):g}"))
        if run is None:
            continue
        leg_neutral = financing_neutral(view(run, SHEET, social, hurdle))
        legs.append({"the reading": leg_row["option"],
                     "it holds": f"{float(leg_row['value']):g} {leg_row['unit']}",
                     "financing-neutral": money(leg_neutral),
                     "blended at the hurdle": money(blended(view(run, SHEET, hurdle, hurdle))),
                     "farmer_bankable": "PASS" if leg_neutral > 0 else "FAIL",
                     "where it comes from": leg_row["cite"]})
    tension_frame = pd.DataFrame(legs)
    split = len({leg["farmer_bankable"] for leg in legs}) > 1
    bars = None
    if go is not None and len(legs):
        def to_number(text):
            stripped = text.strip("()\u20ac").replace(",", "")
            return -float(stripped) if text.startswith("(") else float(stripped)
        bar_figure = go.Figure()
        for bar_index, bar_column in enumerate(["financing-neutral", "blended at the hurdle"]):
            bar_figure.add_trace(go.Bar(
                name=bar_column, x=list(tension_frame["it holds"]),
                y=[to_number(cell_value) for cell_value in tension_frame[bar_column]],
                marker_color=("#1f6f8b", "#c04a35")[bar_index]))
        bar_figure.update_layout(height=320, barmode="group", yaxis_title="EUR",
                                 title=f"Both readings of {tension_picker.value}")
        bars = mo.ui.plotly(bar_figure)
    cashflow_rows = pack["cashflow"]
    mo.vstack([
        mo.md(
            f"## **{tension_picker.value}**, priced\n\n"
            "Each row is a complete pass of the exercise spreadsheet at that reading - not a scaled "
            "guess, a run - priced at the rates you set above. "
            + ("The verdict turns on which side you take: one reading leaves the farm above water and "
               "the other does not." if split else
               "Both readings clear the same verdict here, so this one is a question about the "
               "financing, not about the farm.")
        ),
        mo.ui.table(tension_frame.drop(columns=["farmer_bankable"]), selection=None),
        *([bars] if bars is not None else [])])
    return (cashflow_rows,)


