@app.cell(hide_code=True)
def _(cashflow_rows, formatted, is_blank, line_items, line_pick, line_provenance, line_sheet, money):
    line_grid = line_items(cashflow_rows, line_sheet.value)
    line_year_cols = [c for c in line_grid.columns if c.startswith("y")]
    line_view = formatted(line_grid, line_year_cols + ["sum across years"], money)
    line_view["first negative year"] = line_grid["first negative year"].map(
        lambda y: "never" if is_blank(y) else f"year {int(y)}")
    line_feed = line_provenance(pack["model_edges"], pack["assumptions"], line_sheet.value,
                                line_pick.value)
    mo.vstack([
        mo.md(
            f"**{line_pick.value}** on {line_sheet.value} is a "
            f"**{line_grid[line_grid['line'] == line_pick.value].iloc[0]['what it is']}** row, read "
            f"cell-for-cell from the values the spreadsheet cached. "
            + ("No assumption cell writes it directly, so it is computed from other rows."
               if line_feed.empty else
               f"{len(line_feed)} assumption cell(s) write it: "
               + ", ".join(f"`{feed_row['assumption']}` at {feed_row['cell']} "
                           f"({money(feed_row['value'])} {feed_row['unit']})".strip()
                           for _, feed_row in line_feed.iterrows()))
            + "\n\n`€0` is a real zero and `—` means the row is a balance rather than a flow, so adding "
            "it across years gives a number that means nothing."
        ),
        *([mo.ui.table(line_feed, selection=None)] if not line_feed.empty else []),
        mo.ui.table(line_view[["line", "what it is"] + line_year_cols + ["sum across years",
                                                                        "first negative year"]],
                    selection=None)])


